type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;

export interface MessageHandlerOptions {
  sessionStore?: SessionStore;
  history?: {enabled: boolean};
}

export function createMessageHandler(orchestrator: ChatOrchestrator, options: MessageHandlerOptions = {}) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    const message = validation.valid ? validation.data : undefined;
    // A history request is not a turn, so it is answered beside ping and never queues behind a streaming answer.
    if (message?.type === 'list_sessions') {
      return wsErrorHandler(ws, () => answerListSessions(ws, session, options, message));
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
  };
}

// Off the lock and never a push: answered when asked. An error, not an empty list, when it cannot be answered.
async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  options: MessageHandlerOptions,
  message: ListSessionsMessage
): Promise<void> {
  const store = options.sessionStore;
  if (!options.history?.enabled || !store?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation list is not available on this server');
    return;
  }
  try {
    const summaries = await store.listFor(session.userId, {limit: message.limit, before: message.before});
    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
  } catch (error) {
    const reason = error instanceof Error ? error.message : 'Unknown error';
